  1→{% comment %}
  2→  Zip Code Checker — Theme App Extension Block
  3→  Add this block to any section in the Shopify Theme Editor.
  4→  The block automatically connects to your app — no manual configuration needed.
  5→{% endcomment %}
  6→
  7→{% if request.design_mode %}
  8→  {% comment %}
  9→    Theme Editor preview — shows two states:
 10→    1. If app embed is active → full widget preview
 11→    2. If app embed is NOT active → "Enable app embed" placeholder
 12→    We check window.__zccAppEnabled which is set by the app embed block.
 13→  {% endcomment %}
 14→  <div id="zcc-editor-{{ block.id }}">
 15→    <!-- Inactive state (shown by default) -->
 16→    <div id="zcc-inactive-{{ block.id }}" style="
 17→      background:#f6f6f7;border:1px dashed #c9cccf;border-radius:8px;
 18→      padding:20px;max-width:480px;text-align:center;
 19→      font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
 20→      color:#6d7175;font-size:13px;box-sizing:border-box;
 21→    ">
 22→      <p style="margin:0 0 6px;font-weight:600;color:#202223;font-size:15px;">Zip Code Checker</p>
 23→      <p style="margin:0 0 4px;">This widget requires the app embed to be enabled.</p>
 24→      <p style="margin:0;font-size:12px;">Go to <strong>App Embeds</strong> and toggle on <strong>Zip Code Checker</strong> to activate.</p>
 25→    </div>
 26→    <!-- Active preview (hidden by default) -->
 27→    <div id="zcc-active-{{ block.id }}" style="display:none;">
 28→      <div style="
 29→        background:#ffffff;
 30→        border:1px solid #e1e3e5;
 31→        border-radius:8px;
 32→        padding:24px;
 33→        max-width:480px;
 34→        font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
 35→        box-sizing:border-box;
 36→        color:#202223;
 37→      ">
 38→        <p style="font-size:16px;font-weight:600;margin:0 0 16px;">Check Delivery Availability</p>
 39→        <div style="display:flex;gap:8px;margin-bottom:12px;">
 40→          <input type="text" placeholder="Enter your zip code" disabled style="
 41→            flex:1;padding:10px 12px;border:1px solid #c9cccf;border-radius:8px;
 42→            font-size:14px;background:#fafbfb;color:#202223;min-width:0;
 43→          ">
 44→          <button type="button" disabled style="
 45→            background:#008060;color:#fff;border:none;border-radius:8px;
 46→            padding:10px 20px;font-size:14px;font-weight:600;white-space:nowrap;
 47→            opacity:0.7;cursor:default;
 48→          ">Check</button>
 49→        </div>
 50→        <div style="
 51→          background:#00806015;border-left:3px solid #008060;border-radius:8px;
 52→          padding:12px;font-size:14px;color:#008060;line-height:1.4;
 53→        ">
 54→          Great news! We deliver to your area.
 55→          <div style="margin-top:4px;font-size:13px;opacity:0.8;">Estimated delivery: 2-3 business days</div>
 56→        </div>
 57→        <p style="margin:12px 0 0;font-size:11px;color:#8c9196;text-align:center;">
 58→          Zip Code Checker — live widget loads on your storefront
 59→        </p>
 60→      </div>
 61→    </div>
 62→  </div>
 63→  <script>
 64→  (function() {
 65→    var bid = "{{ block.id }}";
 66→    function check() {
 67→      if (window.__zccAppEnabled) {
 68→        var inactive = document.getElementById('zcc-inactive-' + bid);
 69→        var active = document.getElementById('zcc-active-' + bid);
 70→        if (inactive) inactive.style.display = 'none';
 71→        if (active) active.style.display = 'block';
 72→      }
 73→    }
 74→    check();
 75→    setTimeout(check, 500);
 76→    setTimeout(check, 1500);
 77→    setTimeout(check, 3000);
 78→  })();
 79→  </script>
 80→{% else %}
 81→
 82→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
 83→
 84→<div
 85→  id="zcc-widget-{{ block.id }}"
 86→  data-zcc-widget="true"
 87→  data-shop="{{ shop.permanent_domain }}"
 88→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
 89→  data-block="{{ block.id }}"
 90→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
 91→  {{ block.shopify_attributes }}
 92→></div>
 93→
 94→<script>
 95→(function () {
 96→  // Wait for app embed to set window.__zccAppEnabled.
 97→  // App embed (target: body) may load after this section block, so we poll briefly.
 98→  var maxWait = 3000; // ms
 99→  var interval = 50;  // ms
100→  var elapsed = 0;
101→
102→  function tryInit() {
103→    if (window.__zccAppEnabled) {
104→      init();
105→    } else if (elapsed < maxWait) {
106→      elapsed += interval;
107→      setTimeout(tryInit, interval);
108→    }
109→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
110→  }
111→
112→  // Start checking — if already set, runs immediately
113→  if (document.readyState === 'loading') {
114→    document.addEventListener('DOMContentLoaded', tryInit);
115→  } else {
116→    tryInit();
117→  }
118→
119→  function init() {
120→  var ROOT_ID = "zcc-widget-{{ block.id }}";
121→  var container = document.getElementById(ROOT_ID);
122→  if (!container) return;
123→
124→  var SHOP = container.dataset.shop;
125→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
126→
127→  // Try embedded config from metafield first (instant, no network needed)
128→  var configStr = container.getAttribute("data-config");
129→  if (configStr) {
130→    try {
131→      renderWidget(JSON.parse(configStr));
132→      return;
133→    } catch (e) {
134→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
135→    }
136→  }
137→
138→  // Fallback: fetch config from API
139→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
140→    .then(function (r) {
141→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
142→      return r.json();
143→    })
144→    .then(function (cfg) { renderWidget(cfg); })
145→    .catch(function (err) {
146→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
147→      renderWidget({});
148→    });
149→
150→  function renderWidget(cfg) {
151→    // Merge with defaults
152→    var D = {
153→      position: "inline",
154→      heading: "Check Delivery Availability",
155→      placeholder: "Enter your zip code",
156→      buttonText: "Check",
157→      successMessage: "Great news! We deliver to your area.",
158→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
159→      notFoundMessage: "We currently do not ship to this ZIP code.",
160→      primaryColor: "#008060",
161→      successColor: "#008060",
162→      errorColor: "#D72C0D",
163→      backgroundColor: "#FFFFFF",
164→      textColor: "#202223",
165→      borderRadius: "8",
166→      showEta: true,
167→      showZone: false,
168→      showWaitlistOnFailure: false,
169→      showCod: true,
170→      showReturnPolicy: true,
171→      showCutoffTime: true,
172→      showDeliveryDays: true,
173→      customCss: "",
174→      blockCartOnInvalid: false,
175→      showSocialProof: true,
176→    };
177→    Object.keys(D).forEach(function (k) {
178→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
179→    });
180→
181→    var rad = cfg.borderRadius + "px";
182→    var WID = "zcc-" + ROOT_ID;
183→
184→    if (cfg.position === "floating") {
185→      renderFloating(cfg, WID, rad);
186→    } else if (cfg.position === "popup") {
187→      renderPopup(cfg, WID, rad);
188→    } else {
189→      renderInline(cfg, WID, rad);
190→    }
191→
192→    // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
193→    // until the customer validates their ZIP code
194→    if (cfg.blockCartOnInvalid) {
195→      blockCartButtonsInitial();
196→    }
197→  }
198→
199→  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
200→  function blockCartButtonsInitial() {
201→    var ATC_SELECTORS = [
202→      'button[name="add"]',
203→      '.product-form__submit',
204→      '[data-product-add]',
205→      '.btn--add-to-cart',
206→      '.product-form button[type="submit"]',
207→      'button.shopify-payment-button__button',
208→      '.shopify-payment-button button',
209→      'button.product-form__cart-submit'
210→    ].join(',');
211→
212→    function doBlock() {
213→      try {
214→        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
215→        atcBtns.forEach(function(b) {
216→          if (!b.closest('[data-zcc-widget]')) {
217→            if (!b.getAttribute('data-zcc-blocked')) {
218→              b.setAttribute('data-zcc-orig-title', b.title || '');
219→            }
220→            b.disabled = true;
221→            b.style.opacity = '0.5';
222→            b.title = 'Please check ZIP code availability first';
223→            b.setAttribute('data-zcc-blocked', 'true');
224→          }
225→        });
226→      } catch(e) {}
227→    }
228→
229→    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
230→    doBlock();
231→    setTimeout(doBlock, 500);
232→    setTimeout(doBlock, 1500);
233→
234→    // MutationObserver for dynamic payment buttons
235→    if (typeof MutationObserver !== 'undefined') {
236→      var observer = new MutationObserver(function() { doBlock(); });
237→      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
238→      if (form) {
239→        observer.observe(form, { childList: true, subtree: true });
240→        setTimeout(function() { observer.disconnect(); }, 10000);
241→      }
242→    }
243→  }
244→
245→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
246→  function injectCss(wid, cfg, rad) {
247→    var css =
248→      "#" + wid + "{" +
249→        "background:" + cfg.backgroundColor + " !important;" +
250→        "color:" + cfg.textColor + " !important;" +
251→        "border-radius:" + rad + " !important;" +
252→        "padding:24px !important;" +
253→        "border:1px solid #e1e3e5 !important;" +
254→        "max-width:480px;" +
255→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
256→        "box-sizing:border-box !important;" +
257→      "}" +
258→      "#" + wid + " *{box-sizing:border-box !important}" +
259→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
260→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
261→      "#" + wid + " .zcc-input{" +
262→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
263→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
264→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
265→      "}" +
266→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
267→      "#" + wid + " .zcc-btn{" +
268→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
269→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
270→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
271→      "}" +
272→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
273→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
274→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
275→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
276→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
277→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
278→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
279→      "#" + wid + " .zcc-wl-input{" +
280→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
281→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
282→      "}" +
283→      "#" + wid + " .zcc-wl-btn{" +
284→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
285→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
286→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
287→      "}" +
288→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
289→      "#" + wid + " .zcc-cutoff{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
290→      "#" + wid + " .zcc-days{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
291→      "#" + wid + " .zcc-cod{margin-top:4px !important;font-size:0.85em !important;font-weight:500 !important}" +
292→      "#" + wid + " .zcc-cod--available{color:#008060 !important}" +
293→      "#" + wid + " .zcc-cod--unavailable{color:#d72c0d !important}" +
294→      "#" + wid + " .zcc-return-policy{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
295→      "#" + wid + " .zcc-social-proof{display:block !important;font-size:0.82em !important;color:#6d7175 !important;margin-bottom:8px !important;font-style:italic !important}" +
296→      (cfg.customCss || "");
297→
298→    var styleEl = document.createElement("style");
299→    styleEl.textContent = css;
300→    document.head.appendChild(styleEl);
301→  }
302→
303→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
304→  function buildWidgetInner(wid, cfg, btnLabel) {
305→    return (
306→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
307→      '<div class="zcc-row">' +
308→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
309→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
310→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
311→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
312→      "</div>" +
313→      '<div id="' + wid + '-res"></div>'
314→    );
315→  }
316→
317→  function wireWidget(wid, cfg, API_BASE, SHOP) {
318→    var inp = document.getElementById(wid + "-inp");
319→    var btn = document.getElementById(wid + "-btn");
320→    var res = document.getElementById(wid + "-res");
321→    var btnLabel = cfg.buttonText;
322→    if (!inp || !btn || !res) return;
323→
324→    function normalizeZip(raw) {
325→      var z = raw.trim().toUpperCase();
326→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
327→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
328→      return z;
329→    }
330→
331→    function checkZip() {
332→      var zip = normalizeZip(inp.value);
333→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
334→      if (!zip) { inp.focus(); return; }
335→
336→      btn.disabled = true;
337→      btn.textContent = "\u2026";
338→      res.innerHTML = "";
339→
340→      fetch(
341→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
342→          "&zip=" + encodeURIComponent(zip)
343→      )
344→        .then(function (r) { return r.json(); })
345→        .then(function (data) {
346→          btn.disabled = false;
347→          btn.textContent = btnLabel;
348→
349→          // Store validation result for cart page
350→          try {
351→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
352→            sessionStorage.setItem('zcc:zip', zip);
353→            sessionStorage.setItem('zcc:shop', SHOP);
354→            // Fire custom event for other scripts to listen to
355→            window.dispatchEvent(new CustomEvent('zcc:validated', {
356→              detail: { valid: data.allowed, zip: zip }
357→            }));
358→          } catch(e) { /* sessionStorage may be unavailable */ }
359→
360→          if (data.allowed) {
361→            var html = '<div class="zcc-result ok">' + esc(data.message);
362→            if (cfg.showEta && data.eta) {
363→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
364→            }
365→            if (cfg.showZone && data.zone) {
366→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
367→            }
368→            if (cfg.showDeliveryDays && data.daysOfWeek) {
369→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
370→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
371→            }
372→            if (cfg.showCutoffTime && data.cutoffTime) {
373→              var parts = data.cutoffTime.split(':');
374→              var hr = parseInt(parts[0], 10);
375→              var min = parts[1] || '00';
376→              var ampm = hr >= 12 ? 'PM' : 'AM';
377→              var hr12 = hr % 12 || 12;
378→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
379→            }
380→            if (data.codAvailable === true) {
381→              html += '<div class="zcc-cod zcc-cod--available">\u2713 Cash on Delivery Available</div>';
382→            } else if (data.codAvailable === false) {
383→              html += '<div class="zcc-cod zcc-cod--unavailable">\u2717 COD Not Available</div>';
384→            }
385→            if (data.returnPolicy) {
386→              html += '<div class="zcc-return-policy">\u21a9 ' + esc(data.returnPolicy) + '</div>';
387→            }
388→            html += "</div>";
389→            res.innerHTML = html;
390→          } else {
391→            var html = '<div class="zcc-result fail">' + esc(data.message);
392→            if (cfg.showWaitlistOnFailure) {
393→              html +=
394→                '<div class="zcc-wl">' +
395→                '<a href="#" id="' + wid + '-wl-toggle" style="display:inline-block;margin-bottom:8px;font-size:13px;font-weight:600;color:' + cfg.primaryColor + ';text-decoration:underline;cursor:pointer">Request ZIP Code</a>' +
396→                '<div id="' + wid + '-wl-form" style="display:none">' +
397→                '<p style="font-size:12px;color:#6d7175;margin:0 0 8px">Request delivery to your area</p>' +
398→                '<input class="zcc-wl-input" type="text" id="' + wid + '-wl-name" placeholder="Your name" style="margin-bottom:6px" />' +
399→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Your email" />' +
400→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Submit Request</button>' +
401→                '</div>' +
402→                "</div>";
403→            }
404→            html += "</div>";
405→            res.innerHTML = html;
406→
407→            if (cfg.showWaitlistOnFailure) {
408→              // Wire "Request ZIP Code" toggle link
409→              var wlToggle = document.getElementById(wid + "-wl-toggle");
410→              var wlForm = document.getElementById(wid + "-wl-form");
411→              if (wlToggle && wlForm) {
412→                wlToggle.addEventListener("click", function(e) {
413→                  e.preventDefault();
414→                  wlForm.style.display = wlForm.style.display === "none" ? "block" : "none";
415→                  wlToggle.style.display = "none";
416→                });
417→              }
418→
419→              // Social proof count
420→              if (cfg.showSocialProof && data.waitlistCount && data.waitlistCount > 0) {
421→                var wlSection = document.getElementById(wid + "-wl-name");
422→                if (wlSection && wlSection.parentNode) {
423→                  var spEl = document.createElement('div');
424→                  spEl.className = 'zcc-social-proof';
425→                  var count = data.waitlistCount;
426→                  spEl.textContent = '\uD83D\uDE4B Join ' + count + ' other' + (count !== 1 ? 's' : '') + ' waiting for delivery to your area';
427→                  wlSection.parentNode.insertBefore(spEl, wlSection);
428→                }
429→              }
430→
431→              var wBtn = document.getElementById(wid + "-wl-btn");
432→              if (wBtn) {
433→                wBtn.addEventListener("click", function () {
434→                  var nameEl = document.getElementById(wid + "-wl-name");
435→                  var emailEl = document.getElementById(wid + "-wl-email");
436→                  var name = nameEl ? nameEl.value.trim() : "";
437→                  var email = emailEl ? emailEl.value.trim() : "";
438→                  if (!email) { if (emailEl) emailEl.focus(); return; }
439→                  joinWaitlist(zip, email, name, wBtn);
440→                });
441→              }
442→            }
443→          }
444→
445→          // Block/unblock Add to Cart based on result (if merchant enabled this)
446→          if (cfg.blockCartOnInvalid) {
447→            var ATC_SELECTORS = [
448→              'button[name="add"]',
449→              '.product-form__submit',
450→              '[data-product-add]',
451→              '.btn--add-to-cart',
452→              '.product-form button[type="submit"]',
453→              'button.shopify-payment-button__button',
454→              '.shopify-payment-button button',
455→              'button.product-form__cart-submit'
456→            ].join(',');
457→
458→            try {
459→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
460→              atcBtns.forEach(function(b) {
461→                if (!b.closest('#zcc-widget, [data-zcc-widget]')) { // Don't touch our own widget's button
462→                  if (data.allowed) {
463→                    b.disabled = false;
464→                    b.style.opacity = '';
465→                    b.title = b.getAttribute('data-zcc-orig-title') || '';
466→                    b.removeAttribute('data-zcc-orig-title');
467→                    b.removeAttribute('data-zcc-blocked');
468→                  } else {
469→                    b.setAttribute('data-zcc-orig-title', b.title || '');
470→                    b.disabled = true;
471→                    b.style.opacity = '0.5';
472→                    b.title = 'Please enter a valid ZIP code to continue';
473→                    b.setAttribute('data-zcc-blocked', 'true');
474→                  }
475→                }
476→              });
477→            } catch(e) { /* DOM query may fail in some contexts */ }
478→          }
479→        })
480→        .catch(function () {
481→          btn.disabled = false;
482→          btn.textContent = btnLabel;
483→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
